<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Bar, Line } from 'vue-chartjs'
import { BarElement, CategoryScale, Chart as ChartJS, Filler, Legend, LinearScale, LineElement, PointElement, Tooltip } from 'chart.js'
import { exportDashboard, getDashboard, type Dashboard } from '@/services/business'
import { useAuthStore } from '@/stores/auth'
import { formatMoney, formatNumber, statusLabel } from '@/utils/format'
import PageHeader from '@/components/PageHeader.vue'
import DataState from '@/components/DataState.vue'
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Legend, Filler)
const auth = useAuthStore(), data = ref<Dashboard>(), error = ref(''), loading = ref(false)
const to = ref(new Date().toISOString().slice(0, 10)), from = ref(new Date(Date.now() - 29 * 86400000).toISOString().slice(0, 10))
const chartOptions = { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: '#eef2f7' } } } }
const revenueTrend = computed(() => ({ labels: data.value?.revenueTrend.map((item) => new Date(item.date).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' })) ?? [], datasets: [{ label: 'Doanh thu', data: data.value?.revenueTrend.map((item) => item.revenue) ?? [], borderColor: '#0891b2', backgroundColor: 'rgba(6,182,212,.12)', tension: .35, fill: true }] }))
const warehouseRevenue = computed(() => ({ labels: data.value?.revenueByWarehouse.map((item) => item.name) ?? [], datasets: [{ label: 'Doanh thu', data: data.value?.revenueByWarehouse.map((item) => item.value) ?? [], backgroundColor: '#0891b2', borderRadius: 6 }] }))
const purchaseTrend = computed(() => ({ labels: data.value?.purchaseTrend.map((item) => new Date(item.date).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' })) ?? [], datasets: [{ label: 'Giá trị nhập', data: data.value?.purchaseTrend.map((item) => item.receivedValue) ?? [], borderColor: '#7c3aed', backgroundColor: 'rgba(124,58,237,.10)', tension: .35, fill: true }] }))
async function load() { loading.value = true; error.value = ''; try { data.value = await getDashboard(from.value, to.value) } catch { error.value = 'Không thể tải số liệu tổng quan. Vui lòng kiểm tra quyền truy cập hoặc thử lại.' } finally { loading.value = false } }
async function downloadCsv() { try { const blob = await exportDashboard(from.value, to.value), url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = `bao-cao-securebiz-${from.value}-${to.value}.csv`; link.click(); URL.revokeObjectURL(url) } catch { error.value = 'Không thể xuất báo cáo. Tài khoản có thể chưa được cấp quyền xuất dữ liệu.' } }
onMounted(() => { if (auth.hasPermission('report.view')) void load() })
</script>

<template>
  <section class="page-shell">
    <PageHeader eyebrow="Tình hình kinh doanh" title="Tổng quan" description="Theo dõi nhanh doanh thu, đơn hàng, nhập hàng và tồn kho trong kỳ.">
      <template #actions><div v-if="auth.hasPermission('report.view')" class="filter-bar !p-2"><label class="sr-only" for="from-date">Từ ngày</label><input id="from-date" v-model="from" type="date" class="input !w-auto" /><span class="hidden text-slate-400 sm:inline">đến</span><label class="sr-only" for="to-date">Đến ngày</label><input id="to-date" v-model="to" type="date" class="input !w-auto" /><button class="btn btn-primary" :disabled="loading" @click="load">Áp dụng</button><button v-if="auth.hasPermission('report.export')" class="btn btn-secondary" @click="downloadCsv">⇩ Xuất CSV</button></div></template>
    </PageHeader>
    <DataState v-if="!auth.hasPermission('report.view')" class="mt-6" type="error" title="Bạn chưa có quyền xem báo cáo" message="Liên hệ quản trị viên để được cấp quyền phù hợp." />
    <DataState v-else-if="loading" class="mt-6" type="loading" />
    <DataState v-else-if="error" class="mt-6" type="error" :message="error" />
    <template v-else-if="data">
      <div class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article v-for="metric in [{ label: 'Doanh thu trong kỳ', value: formatMoney(data.summary.revenue), icon: '↗', tone: 'text-cyan-700 bg-cyan-50' }, { label: 'Số hóa đơn', value: formatNumber(data.summary.orders), icon: '▤', tone: 'text-blue-700 bg-blue-50' }, { label: 'Giá trị trung bình', value: formatMoney(data.summary.averageOrderValue), icon: '◎', tone: 'text-violet-700 bg-violet-50' }, { label: 'Giá trị tồn kho', value: formatMoney(data.summary.inventoryValue), icon: '◇', tone: 'text-amber-700 bg-amber-50' }, { label: 'Giá trị nhập hàng', value: formatMoney(data.summary.purchaseValue), icon: '↓', tone: 'text-emerald-700 bg-emerald-50' }]" :key="metric.label" class="metric-card"><div class="flex items-start justify-between gap-2"><p class="metric-label">{{ metric.label }}</p><span class="grid h-9 w-9 place-items-center rounded-xl" :class="metric.tone">{{ metric.icon }}</span></div><p class="metric-value">{{ metric.value }}</p></article></div>
      <div class="mt-5 grid gap-5 xl:grid-cols-2"><article class="panel p-5"><h2 class="font-bold">Doanh thu theo ngày</h2><p class="text-xs text-slate-500">Xu hướng doanh thu trong khoảng thời gian đã chọn</p><div class="mt-4 h-72"><Line :data="revenueTrend" :options="chartOptions" /></div></article><article class="panel p-5"><h2 class="font-bold">Doanh thu theo kho</h2><p class="text-xs text-slate-500">So sánh hiệu quả giữa các điểm bán</p><div class="mt-4 h-72"><Bar :data="warehouseRevenue" :options="chartOptions" /></div></article><article class="panel p-5"><h2 class="font-bold">Nhập hàng theo ngày</h2><p class="text-xs text-slate-500">Giá trị hàng đã thực nhận</p><div class="mt-4 h-72"><Line :data="purchaseTrend" :options="chartOptions" /></div></article><article class="panel p-5"><h2 class="font-bold">Doanh thu theo nhân viên</h2><div class="mt-3 divide-y"><div v-for="(employee, index) in data.revenueByEmployee" :key="employee.name" class="flex items-center justify-between gap-4 py-3"><span class="flex items-center gap-3"><b class="grid h-7 w-7 place-items-center rounded-full bg-slate-100 text-xs">{{ index + 1 }}</b><span>{{ employee.name }}<small class="block text-slate-500">{{ employee.orders }} hóa đơn</small></span></span><b>{{ formatMoney(employee.revenue) }}</b></div><p v-if="!data.revenueByEmployee.length" class="py-10 text-center text-sm text-slate-400">Chưa có dữ liệu trong kỳ.</p></div></article></div>
      <div class="mt-5 grid gap-5 xl:grid-cols-3"><article class="panel p-5"><h2 class="font-bold">Biến động kho</h2><div class="mt-3 divide-y"><p v-for="movement in data.stockMovements" :key="movement.type" class="flex justify-between py-3 text-sm"><span>{{ statusLabel(movement.type) }}</span><b :class="movement.quantity < 0 ? 'text-red-700' : 'text-emerald-700'">{{ movement.quantity > 0 ? '+' : '' }}{{ formatNumber(movement.quantity) }}</b></p><p v-if="!data.stockMovements.length" class="py-8 text-center text-sm text-slate-400">Chưa có biến động kho.</p></div></article><article class="panel p-5"><h2 class="font-bold">Sản phẩm bán chạy</h2><div class="mt-3 divide-y"><p v-for="(product, index) in data.topProducts" :key="product.name" class="flex justify-between gap-3 py-3 text-sm"><span><b class="mr-2 text-slate-400">{{ index + 1 }}</b>{{ product.name }}</span><b>{{ formatNumber(product.value) }}</b></p><p v-if="!data.topProducts.length" class="py-8 text-center text-sm text-slate-400">Chưa có dữ liệu bán hàng.</p></div></article><article class="panel p-5"><div class="flex justify-between"><h2 class="font-bold">Hàng sắp hết</h2><RouterLink to="/inventory" class="text-xs font-semibold text-cyan-700">Xem tồn kho →</RouterLink></div><div class="mt-3 divide-y"><div v-for="item in data.lowStock" :key="item.warehouse + item.sku" class="flex justify-between gap-3 py-3 text-sm"><span><b>{{ item.product }}</b><small class="block font-mono text-slate-500">{{ item.sku }} · {{ item.warehouse }}</small></span><span class="self-center rounded-full bg-amber-50 px-2 py-1 font-semibold text-amber-700">{{ formatNumber(item.quantity) }} / {{ formatNumber(item.reorderLevel) }}</span></div><p v-if="!data.lowStock.length" class="py-8 text-center text-sm text-emerald-700">Tồn kho đang ở mức an toàn.</p></div></article></div>
    </template>
  </section>
</template>
